<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useDisplay } from 'vuetify'
import { salesDocumentsApi } from '@/api/salesDocuments'
import { customersApi } from '@/api/customers'
import { productsApi } from '@/api/products'
import { useOrganizationContextStore } from '@/stores/organizationContext'
import { useApiError } from '@/composables/useApiError'
import { usePermission } from '@/composables/usePermission'
import AppMoneyField from '@/components/AppMoneyField.vue'
import AppMobileRecordCard from '@/components/AppMobileRecordCard.vue'
import type { Customer, Product } from '@/types/models'
import type { SalesDocument, SalesDocumentAudit, SalesDocumentPayload, SalesDocumentType } from '@/types/salesDocuments'
const {t}=useI18n(); const {mdAndUp}=useDisplay(); const {can}=usePermission(); const org=useOrganizationContextStore(); const error=useApiError();
const rows=ref<SalesDocument[]>([]),customers=ref<Customer[]>([]),products=ref<Product[]>([]),audits=ref<SalesDocumentAudit[]>([]),loading=ref(false),saving=ref(false),editor=ref(false),detail=ref(false),selected=ref<SalesDocument|null>(null),notice=ref('');
const form=reactive({id:null as number|null,version:undefined as number|undefined,companyId:null as number|null,branchId:null as number|null,customerId:null as number|null,documentType:'QUOTATION' as SalesDocumentType,currency:'IRR',notes:'',lines:[{productId:null as number|null,quantity:1,unitPrice:0,discount:0}]});
const total=computed(()=>form.lines.reduce((s,l)=>s+l.unitPrice*l.quantity-l.discount,0)); const label=(x:string)=>t(`enum.${x}`,x); const money=(x:number)=>new Intl.NumberFormat(undefined,{maximumFractionDigits:0}).format(x);
async function load(){if(!org.companyId||!org.branchId)return;loading.value=true;try{rows.value=await salesDocumentsApi.list(org.companyId,org.branchId)}catch(e){error.set(e)}finally{loading.value=false}}
async function lookups(){const[c,p]=await Promise.all([customersApi.list({size:100}),productsApi.list({size:100})]);customers.value=c.content;products.value=p.content}
function open(row?:SalesDocument){Object.assign(form,{id:row?.id??null,version:row?.version,companyId:row?.companyId??org.companyId,branchId:row?.branchId??org.branchId,customerId:row?.customerId??null,documentType:row?.documentType??'QUOTATION',currency:row?.currency??'IRR',notes:row?.notes??'',lines:row?.lines.map(l=>({productId:l.productId,quantity:l.quantity,unitPrice:l.unitPrice,discount:l.discount}))??[{productId:null,quantity:1,unitPrice:0,discount:0}]});editor.value=true;void lookups()}
function product(line:{productId:number|null;unitPrice:number}){const p=products.value.find(x=>x.id===line.productId);if(p&&line.unitPrice===0)line.unitPrice=p.price}
async function save(){if(saving.value)return;if(!form.companyId||!form.branchId||!form.customerId||form.lines.some(l=>!l.productId||l.quantity<=0||l.discount>l.quantity*l.unitPrice)){error.set({code:'VALIDATION',message:'Invalid sales document'});return}saving.value=true;try{const p:SalesDocumentPayload={companyId:form.companyId,branchId:form.branchId,customerId:form.customerId,documentType:form.documentType,currency:form.currency,notes:form.notes||undefined,lines:form.lines.map(l=>({productId:l.productId!,quantity:l.quantity,unitPrice:l.unitPrice,discount:l.discount||undefined})),expectedVersion:form.version};const r=form.id?await salesDocumentsApi.update(form.id,p):await salesDocumentsApi.create(p);editor.value=false;notice.value=t('salesDocuments.saved');await load();await show(r)}catch(e){error.set(e)}finally{saving.value=false}}
async function show(row:SalesDocument){try{const [document,audit]=await Promise.all([salesDocumentsApi.get(row.id),salesDocumentsApi.audit(row.id)]);selected.value=document;audits.value=audit;detail.value=true}catch(e){error.set(e)}}
async function action(kind:'issue'|'cancel'|'expire'){if(!selected.value||saving.value)return;saving.value=true;try{selected.value=await salesDocumentsApi[kind](selected.value.id);notice.value=t('salesDocuments.saved');await load()}catch(e){error.set(e)}finally{saving.value=false}}
onMounted(async()=>{if(!org.context)await org.refresh();await load()})
</script>
<template><section><v-alert v-if="!org.companyId||!org.branchId" type="warning" variant="tonal">{{t('salesDocuments.scopeRequired')}}</v-alert><v-alert v-if="notice" type="success" variant="tonal" class="mb-3">{{notice}}</v-alert><v-alert v-if="error.message.value" type="error" variant="tonal" class="mb-3">{{error.message.value}}</v-alert><v-card class="app-data-surface" rounded="xl"><v-card-title class="d-flex align-center"><span>{{t('salesDocuments.title')}}</span><v-spacer/><v-btn v-if="can('sales:create')" color="primary" prepend-icon="mdi-file-plus-outline" :disabled="!org.companyId||!org.branchId" @click="open()">{{t('salesDocuments.new')}}</v-btn></v-card-title><v-card-text><v-data-table v-if="mdAndUp" :headers="[{title:t('salesDocuments.number'),key:'number'},{title:t('salesDocuments.type'),key:'documentType'},{title:t('salesDocuments.status'),key:'status'},{title:t('salesDocuments.total'),key:'finalAmount'},{title:'',key:'actions'}]" :items="rows" :loading="loading"><template #item.documentType="{item}">{{label(item.documentType)}}</template><template #item.status="{item}"><v-chip size="small">{{label(item.status)}}</v-chip></template><template #item.finalAmount="{item}">{{money(item.finalAmount)}}</template><template #item.actions="{item}"><v-btn icon="mdi-eye-outline" variant="text" @click="show(item)"/></template></v-data-table><div v-else class="d-grid ga-3"><AppMobileRecordCard v-for="row in rows" :key="row.id" :label="row.number" @open="show(row)"><div>{{label(row.documentType)}} · {{label(row.status)}} · {{money(row.finalAmount)}}</div></AppMobileRecordCard></div></v-card-text></v-card><v-dialog v-model="editor" :fullscreen="!mdAndUp" max-width="960"><v-card><v-toolbar color="transparent"><v-toolbar-title>{{form.id?t('common.edit'):t('salesDocuments.new')}}</v-toolbar-title><v-btn icon="mdi-close" @click="editor=false"/></v-toolbar><v-card-text><v-row><v-col cols="12" sm="4"><v-select v-model="form.documentType" :items="[{title:t('salesDocuments.quotation'),value:'QUOTATION'},{title:t('salesDocuments.proforma'),value:'PROFORMA'}]" :label="t('salesDocuments.type')"/></v-col><v-col cols="12" sm="8"><v-autocomplete v-model="form.customerId" :items="customers" item-title="displayName" item-value="id" :label="t('sales.customer')"/></v-col><v-col cols="12"><v-textarea v-model="form.notes" :label="t('sales.notes')"/></v-col></v-row><v-card v-for="(line,i) in form.lines" :key="i" variant="outlined" class="pa-3 mb-3"><v-row><v-col cols="12" md="5"><v-autocomplete v-model="line.productId" :items="products" item-title="name" item-value="id" :label="t('sales.product')" @update:model-value="product(line)"/></v-col><v-col cols="4" md="2"><v-text-field v-model.number="line.quantity" type="number" min="0.001" :label="t('sales.quantity')"/></v-col><v-col cols="4" md="2"><AppMoneyField v-model="line.unitPrice" :label="t('sales.unitPrice')"/></v-col><v-col cols="4" md="2"><AppMoneyField v-model="line.discount" :label="t('sales.discount')"/></v-col><v-col cols="12" md="1"><v-btn icon="mdi-delete-outline" variant="text" :disabled="form.lines.length===1" @click="form.lines.splice(i,1)"/></v-col></v-row></v-card><v-btn variant="tonal" prepend-icon="mdi-plus" @click="form.lines.push({productId:null,quantity:1,unitPrice:0,discount:0})">{{t('sales.addItem')}}</v-btn><div class="text-end text-h6 mt-4">{{t('salesDocuments.total')}}: {{money(total)}}</div></v-card-text><v-card-actions><v-spacer/><v-btn @click="editor=false">{{t('common.cancel')}}</v-btn><v-btn color="primary" :loading="saving" :disabled="!form.customerId||form.lines.some(l=>!l.productId||l.quantity<=0||l.discount>l.quantity*l.unitPrice)" @click="save">{{t('common.save')}}</v-btn></v-card-actions></v-card></v-dialog><v-dialog v-model="detail" :fullscreen="!mdAndUp" max-width="760"><v-card v-if="selected"><v-toolbar color="transparent"><v-toolbar-title>{{selected.number}}</v-toolbar-title><v-chip>{{label(selected.status)}}</v-chip><v-btn icon="mdi-close" @click="detail=false"/></v-toolbar><v-card-text><div v-for="l in selected.lines" :key="l.id" class="d-flex justify-space-between py-2"><span>{{l.name}} × {{l.quantity}}</span><strong>{{money(l.lineTotal)}}</strong></div><div class="text-end text-h6">{{t('salesDocuments.total')}}: {{money(selected.finalAmount)}}</div><v-divider class="my-4"/><div class="text-subtitle-2 mb-2">{{t('salesDocuments.history')}}</div><v-list density="compact"><v-list-item v-for="audit in audits" :key="audit.id" :title="label(audit.action)" :subtitle="audit.occurredAt"/></v-list></v-card-text><v-card-actions><v-btn v-if="selected.status==='DRAFT'&&can('sales:edit')" @click="open(selected);detail=false">{{t('common.edit')}}</v-btn><v-spacer/><v-btn v-if="selected.status==='DRAFT'&&can('sales:confirm')" color="primary" :loading="saving" @click="action('issue')">{{t('salesDocuments.issue')}}</v-btn><v-btn v-if="selected.status==='ISSUED'&&can('sales:edit')" color="warning" variant="tonal" @click="action('expire')">{{t('salesDocuments.expire')}}</v-btn><v-btn v-if="['DRAFT','ISSUED'].includes(selected.status)&&can('sales:edit')" color="error" variant="tonal" @click="action('cancel')">{{t('salesDocuments.cancel')}}</v-btn></v-card-actions></v-card></v-dialog></section></template>
